/**
 * @param {Function[]} functions
 * @param {number} n
 * @return {Promise<any>}
 */
var promisePool = async function(functions, n) {
    // Index of the next function to start (shared by all workers)
    let next = 0;

    // A worker keeps pulling the next function until none are left
    const worker = async () => {
        while (next < functions.length) {
            const fn = functions[next++];   // claim it synchronously
            await fn();                     // wait for it to finish
        }
    };

    // Launch up to n workers (fewer if there aren't that many functions)
    const workers = [];
    for (let i = 0; i < Math.min(n, functions.length); i++) {
        workers.push(worker());
    }

    // Resolve once every worker has finished
    await Promise.all(workers);
};
